mapper.select:
select tt.* from (select clc.CHANCE_ID, clc.CREDIT_LINE_NUMBER, clc.CREDIT_LINE_NAME, clc.BP_ID, clc.AUTHORITY_RULE_STRING, clc.CREATED_BY, (SELECT WM_CONCAT(distinct a.description) FROM sys_user a, (SELECT ART.ASSIGNEE_, EE.CHANCE_ID FROM act_ru_task ART, (SELECT CC.CHANCE_ID, substr(HSO.NOTICE_URL, (instr(HSO.NOTICE_URL, 'processInstanceId') + 18)) AS A FROM hls_system_notice HSO, (SELECT HSE.EVENT_ID, HCLC.CHANCE_ID FROM hls_system_event HSE, HLS_CREDIT_LINE_CHANCE HCLC WHERE HSE.SOURCE_DOCUMENT_ID = HCLC.CHANCE_ID) CC WHERE CC.EVENT_ID = HSO.NOTICE_ID and instr(HSO.NOTICE_URL, 'processInstanceId') > 0) EE WHERE ART.PROC_INST_ID_ = EE.A) PERSON WHERE a.user_id = PERSON.ASSIGNEE_ and clc.chance_id=person.CHANCE_ID) PERSON_N, (select wm_concat(hbm.bp_name) FROM hls_bp_master hbm, Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = clc.chance_id and hbm.bp_id = hclcb.bp_id and hclcb.bp_type in ('MANUFACTURER') ) bp_name,
(select wm_concat(hclcb.bp_name) FROM Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = clc.chance_id and hclcb.bp_type in ('TENANT','TENANT_SEC') ) bp_id_n, ( select hmr.MARKETING_REPORT_NUMBER from hls_marketing_report hmr where hmr.MARKETING_REPORT_ID = clc.MARKETING_REPORT_ID )MARKETING_REPORT_NUMBER, (select hcp.credit_amt from hls_credit_plan hcp where hcp.source_document_id = clc.chance_id and hcp.source_document_category = 'HLS_CREDIT_LINE_CHANCE') credit_line_amt, CLC.CREDIT_EXPOSURE_AMT, CLC.VALID_TO, clc.CREDIT_FLAG, clc.APPROVED_DATE, ( select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and scv.value = clc.CREDIT_FLAG and sc.CODE = 'SYS.YES_NO' and rownum=1 )CREDIT_FLAG_N, clc.BUSINESS_TYPE, (select v.description from hls_business_type v where v.enabled_flag = 'Y' and v.DOCUMENT_CATEGORY = 'CHANCE' and clc.BUSINESS_TYPE = V.business_type) BUSINESS_TYPE_N, clc.PROPOSER_EMPLOYEE_ID , (SELECT a.description FROM sys_user a WHERE a.user_id = clc.PROPOSER_EMPLOYEE_ID) as PROPOSER_EMPLOYEE_ID_N,
clc.PROJECT_ASSISTANT , (SELECT a.description FROM sys_user a WHERE a.user_id = clc.PROJECT_ASSISTANT) as PROJECT_ASSISTANT_N, clc.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=clc.unit_id) as unit_id_n, CLC.CREDIT_LINE_STATUS, (select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'CREDIT.APPROVE_STATUS' and scv.value = clc.credit_line_status) AS credit_line_status_desc, CLC.VALID_FROM, to_char(clc.CREATION_DATE, 'yyyy-mm-dd') TOUCH_CREATED_DATE from HLS_CREDIT_LINE_CHANCE CLC where nvl(CLC.DATA_TYPE, 'NORMAL') not in ('CHANGE_REQ', 'HISTORY', 'CHANGE_REQ_HISTORY')
and clc.chance_type = 'CREDIT' order by clc.CREATION_DATE desc )tt
1=1
and (tt.PROPOSER_EMPLOYEE_ID = #{createdBy} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}) OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN(select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=tt.PROPOSER_EMPLOYEE_ID AND a.employee_assign_id=b.employee_assign_id)))
and tt.credit_line_number like #{creditLineNumber}
and tt.credit_line_name like #{creditLineName}
and tt.project_reviewer_desc like #{projectReviewer}
and tt.CREDIT_LINE_AMT=#{creditLineAmt}
and tt.credit_line_status=#{creditLineStatus}
and tt.proposer_employee_id=#{proposerEmployeeId}
and tt.project_assistant=#{projectAssistant}
and tt.CREDIT_LINE_STATUS=#{creditLineStatus}
and tt.CREDIT_LINE_AMT >= #{limitFrom}
and tt.CREDIT_LINE_AMT <= #{limitTo}
and tt.VALID_FROM >= #{validFrom}
and tt.VALID_TO < (#{endDate} + 1)
and (select wm_concat(hclcb.bp_name) FROM Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = tt.chance_id and hclcb.bp_type in ('TENANT','TENANT_SEC') and hclcb.bp_id = #{bpId} ORDER BY c ) bp_name like concat(concat('%',#{bpName}),'%')
and tt.marketing_report_id = #{marketingReportNumber}
and tt.BUSINESS_TYPE = #{businessType}
and tt.bp_name like concat(concat('%',#{bpName}),'%')
and tt.credit_flag = #{creditFlag}
and tt.UNIT_ID = #{unitId}

select tt.* from (select clc.CHANCE_ID, clc.creation_date, nvl(clc.process_instance_id,0) as process_instance_id, clc.CREDIT_LINE_NUMBER, clc.CREDIT_LINE_NAME, clc.BP_ID, clc.AUTHORITY_RULE_STRING, clc.CREATED_BY,(SELECT max( END_TIME_ ) FROM ACT_HI_PROCINST ahp WHERE ahp.BUSINESS_KEY_ = clc.CHANCE_ID and CLC.CREDIT_LINE_STATUS='APPROVED' ) approved_time, (select WM_CONCAT(distinct r.description) from sys_user r where r.USER_ID in ( select c.USER_ID from SYS_USER_ALLOCATION c where c.ALLOCATION_ID in (select a2.ASSIGNEE_ from ACT_HI_PROCINST a1,ACT_RU_TASK a2 where a1.PROC_INST_ID_=a2.PROC_INST_ID_ and a1.BUSINESS_KEY_=clc.CHANCE_ID and a1.PROC_DEF_ID_ like '%FCT_PROJECTCREATE_WFL%' ))) PERSON_N, (select wm_concat(hbm.bp_name) FROM hls_bp_master hbm, Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = clc.chance_id and hbm.bp_id = hclcb.bp_id and hclcb.bp_type in ('TENANT', 'TENANT_SEC', 'ASSET_TRANSFEROR', 'ACCOUNTS_RECEIVABLE','MANUFACTURER') ) bp_name,
(select wm_concat(hbm.bp_name) FROM hls_bp_master hbm WHERE hbm.BP_ID = clc.BP_ID ) bp_id_n, ( select WM_CONCAT(hmr.MARKETING_REPORT_NUMBER) from hls_marketing_report hmr where hmr.MARKETING_REPORT_ID = clc.MARKETING_REPORT_ID ) MARKETING_REPORT_NUMBER, nvl(CLC.credit_line_amt,(select q.finance_amount from prj_quotation q where q.source_document_id = clc.chance_id and q.source_document_category = 'HLS_CREDIT_LINE_CHANCE'))credit_line_amt, nvl(CLC.credit_line_amt/10000,(select q.finance_amount/10000 from prj_quotation q where q.source_document_id = clc.chance_id and q.source_document_category = 'HLS_CREDIT_LINE_CHANCE'))credit_line_amt_w, CLC.CREDIT_EXPOSURE_AMT, CLC.VALID_TO, CASE CLC.CREDIT_FLAG WHEN '1' THEN '是' WHEN '2' THEN '否' END CREDIT_FLAG, ( select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and scv.value = clc.CREDIT_FLAG and sc.CODE = 'SYS.YES_NO' and rownum=1 ) CREDIT_FLAG_N, clc.APPROVED_DATE, clc.BUSINESS_TYPE, (select v.description from hls_business_type v where v.enabled_flag = 'Y' and v.DOCUMENT_CATEGORY = 'CHANCE' and clc.BUSINESS_TYPE = V.business_type) BUSINESS_TYPE_N, clc.PROPOSER_EMPLOYEE_ID , (select s.description from sys_user s,sys_user_allocation sa where s.user_id = sa.user_id and sa.allocation_id = clc.proposer_employee_id) as proposer_employee_id_n,
clc.PROJECT_ASSISTANT , (SELECT WM_CONCAT(a.description) FROM sys_user a WHERE a.user_id = clc.PROJECT_ASSISTANT) as PROJECT_ASSISTANT_N, clc.unit_id, (select WM_CONCAT(fou.unit_name) from fnd_org_unit fou where fou.unit_id=clc.unit_id) as unit_id_n, CLC.CREDIT_LINE_STATUS, (select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'CREDIT.APPROVE_STATUS' and scv.value = clc.credit_line_status) AS credit_line_status_desc, CLC.VALID_FROM, to_char(clc.CREATION_DATE, 'yyyy-mm-dd') TOUCH_CREATED_DATE from HLS_CREDIT_LINE_CHANCE CLC where CLC.credit_line_status not in('CLOSED') and nvl(CLC.DATA_TYPE, 'NORMAL') not in ('CHANGE_REQ', 'HISTORY', 'CHANGE_REQ_HISTORY') and CLC.document_type= 'CREDIT' order by clc.CREATION_DATE desc )tt
1=1
and ( tt.created_by = #{createdBy} or tt.PROJECT_ASSISTANT = #{createdBy} or #{request.employeeCode} in('ADMIN') OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN(select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=tt.created_by AND a.employee_assign_id=b.employee_assign_id)) )
and tt.credit_line_number like #{creditLineNumber}
and tt.credit_line_name like #{creditLineName}
and tt.project_reviewer_desc like #{projectReviewer}
and tt.CREDIT_LINE_AMT=#{creditLineAmt}
and tt.credit_line_status=#{creditLineStatus}
and tt.proposer_employee_id=#{proposerEmployeeId}
and tt.project_assistant=#{projectAssistant}
and tt.CREDIT_LINE_STATUS=#{creditLineStatus}
and to_date(tt.touch_created_date,'YYYY/MM/DD') >= to_date(#{touchCreatedDateFrom},'YYYY/MM/DD')
and to_date(tt.touch_created_date,'YYYY/MM/DD') <= to_date(#{touchCreatedDateTo},'YYYY/MM/DD')
and tt.CREDIT_LINE_AMT >= #{limitFrom}
and tt.CREDIT_LINE_AMT <= #{limitTo}
and tt.VALID_FROM >= #{validFrom}
and tt.VALID_TO < (#{endDate} + 1)
and (select wm_concat(hclcb.bp_name) FROM Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = tt.chance_id and hclcb.bp_type in ('TENANT','TENANT_SEC') and hclcb.bp_id = #{bpId} ) bp_name like concat(concat('%',#{bpName}),'%')
and tt.marketing_report_id = #{marketingReportNumber}
and tt.BUSINESS_TYPE = #{businessType}
and tt.bp_name like concat(concat('%',#{bpName}),'%')
and tt.credit_flag = #{creditFlag}
and tt.UNIT_ID = #{unitId}

select * from (SELECT clc.marketing_report_number as marketing_report_id , hmr.marketing_report_number , clc.project_reviewer, (SELECT su.description FROM sys_user_allocation sua ,sys_user su where sua.user_id = su.user_id and clc.project_reviewer = sua.allocation_id and sua.company_id = clc.company_id ) as project_reviewer_desc, clc.PROPOSER_EMPLOYEE_ID , (SELECT a.description FROM sys_user a WHERE a.user_id = clc.PROPOSER_EMPLOYEE_ID) as PROPOSER_EMPLOYEE_NAME, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = clc.unit_id )as proposer_employee_part, clc.PROJECT_ASSISTANT, (SELECT a.description FROM sys_user a WHERE a.user_id =clc.PROJECT_ASSISTANT) AS PROJECT_ASSISTANT_NAME, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE clc.assit_unit_id = fou.unit_id) as PROJECT_ASSISTANT_PART, CLC.CHANCE_ID, CLC.BP_ID, (select LISTAGG(hclcb.bp_name, ',') WITHIN GROUP(ORDER BY hclcb.bp_id) FROM Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = clc.chance_id and hclcb.bp_type in ('TENANT','TENANT_SEC') ) bp_name, (select LISTAGG(hclcb.bp_name, ',') WITHIN GROUP(ORDER BY hclcb.bp_id) FROM Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = clc.chance_id and hclcb.bp_type in ('TENANT','TENANT_SEC') ) bp_id_n, CLC.CREDIT_LINE_NUMBER, CLC.CREDIT_LINE_NAME, (CLC.CREDIT_LINE_NUMBER || CLC.CREDIT_LINE_NAME) AS CREDIT_NUM, (SELECT FC.COMPANY_FULL_NAME FROM FND_COMPANY FC WHERE CLC.COMPANY_ID = FC.COMPANY_ID ) AS COMPANY_NAME, CLC.CREDIT_LINE_AMT, CLC.CREDIT_EXPOSURE_AMT, CLC.VALID_FROM, CLC.VALID_TO, CLC.CREDIT_LINE_STATUS, (select scv.MEANING from sys_code_b sc, sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'CREDIT.APPROVE_STATUS' and scv.value = clc.credit_line_status) AS credit_line_status_desc, CLC.CREATION_DATE touch_created_date FROM HLS_CREDIT_LINE_CHANCE CLC,hls_marketing_report hmr where 1=1 AND CLC.company_id = #{request.companyId} AND CLC.DOCUMENT_CATEGORY='HLS_CREDIT_LINE' AND clc.credit_line_status != 'NEW' and hmr.marketing_report_id = clc.marketing_report_number order by clc.creation_date desc) v
and v.credit_line_number like #{creditLineNumber}
and v.credit_line_name like #{creditLineName}
and v.project_reviewer_desc like #{projectReviewer}
and v.CREDIT_LINE_AMT=#{creditLineAmt}
and v.credit_line_status=#{creditLineStatus}
and v.proposer_employee_id=#{proposerEmployeeId}
and v.project_assistant=#{projectAssistant}
and v.CREDIT_LINE_STATUS=#{creditLineStatus}
and v.CREDIT_LINE_AMT >= #{limitFrom}
and v.CREDIT_LINE_AMT <= #{limitTo}
and v.VALID_FROM >= #{beginDate}
and v.VALID_TO < (#{endDate} + 1)
and v.bp_name like concat(concat('%',#{bpName}),'%')
and v.marketing_report_id = #{marketingReportNumber}

select clc.credit_line_status, ( select scvb.MEANING from sys_code_b scb, sys_code_value_b scvb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'CON.CONTRACT_PROCESS_STATUS' and scvb.value = clc.credit_line_status ) as credit_line_status_value, count(chance_id) as credit_line_chance_count, round(count(chance_id)/(select count(chance_id) from hls_credit_line_chance
1=1 AND DOCUMENT_CATEGORY = 'HLS_CREDIT_LINE' AND company_id = #{request.companyId}
),2)*100 as credit_line_count_percent from hls_credit_line_chance clc
1=1 AND DOCUMENT_CATEGORY = 'HLS_CREDIT_LINE' AND company_id = #{request.companyId}
group by clc.credit_line_status

SELECT CLC.CHANCE_ID, CLC.BP_ID, ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE CLC.BP_ID = HBM.BP_ID ) AS BP_NAME, CLC.CREDIT_LINE_NUMBER, CLC.CREDIT_LINE_NAME, ( SELECT FC.COMPANY_FULL_NAME FROM FND_COMPANY FC WHERE CLC.COMPANY_ID = FC.COMPANY_ID ) AS COMPANY_NAME, CLC.CREDIT_LINE_AMT, CLC.CREDIT_EXPOSURE_AMT, CLC.VALID_FROM, CLC.VALID_TO, CLC.CREDIT_LINE_STATUS FROM HLS_CREDIT_LINE_CHANCE CLC
1=1 AND CLC.DOCUMENT_CATEGORY='HLS_CREDIT_LINE' AND CLC.COMPANY_ID=#{request.companyId}
and CLC.CREDIT_LINE_AMT >= #{limitFrom}
and CLC.CREDIT_LINE_AMT <= #{limitTo}
and CLC.VALID_FROM >= #{beginDate}
and CLC.VALID_TO < (#{endDate} + 1)
and ( SELECT HBM.BP_NAME FROM HLS_BP_MASTER HBM WHERE CLC.BP_ID = HBM.BP_ID ) like concat(concat('%',#{bpName}),'%')

select tt.* from (select clc.CHANCE_ID, clc.creation_date, nvl(clc.process_instance_id,0) as process_instance_id, clc.CREDIT_LINE_NUMBER, clc.CREDIT_LINE_NAME, clc.INDUSTRY, (select v.MEANING from sys_code_value_b_v v where v.code='CHANCE.INDUSTRY' and v.code_value = clc.INDUSTRY) as INDUSTRY_N, CLC.BP_ID, clc.AUTHORITY_RULE_STRING, clc.CREATED_BY, (SELECT max( END_TIME_ ) FROM ACT_HI_PROCINST ahp WHERE ahp.BUSINESS_KEY_ = clc.CHANCE_ID and CLC.CREDIT_LINE_STATUS='APPROVED' ) approved_time, (select WM_CONCAT(distinct r.description) from sys_user r where r.USER_ID in ( select c.USER_ID from SYS_USER_ALLOCATION c where c.ALLOCATION_ID in (select a2.ASSIGNEE_ from ACT_HI_PROCINST a1,ACT_RU_TASK a2 where a1.PROC_INST_ID_=a2.PROC_INST_ID_ and a1.BUSINESS_KEY_=clc.CHANCE_ID and a1.PROC_DEF_ID_ like '%FCT_PROJECTCREATE_WFL%' ))) PERSON_N, (select wm_concat(hbm.bp_name) FROM hls_bp_master hbm, Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = clc.chance_id and hbm.bp_id = hclcb.bp_id and hclcb.bp_type in ('TENANT', 'TENANT_SEC', 'ASSET_TRANSFEROR', 'ACCOUNTS_RECEIVABLE','MANUFACTURER') ) bp_name,
(select wm_concat(hclcb.bp_name) FROM Hls_Credit_Line_Chance_Bp hclcb WHERE hclcb.chance_id = clc.chance_id and hclcb.bp_type in ('TENANT','TENANT_SEC') ) bp_id_n, ( select hmr.MARKETING_REPORT_NUMBER from hls_marketing_report hmr where hmr.MARKETING_REPORT_ID = clc.MARKETING_REPORT_ID )MARKETING_REPORT_NUMBER, nvl(CLC.credit_line_amt,(select q.finance_amount from prj_quotation q where q.source_document_id = clc.chance_id and q.source_document_category = 'HLS_CREDIT_LINE_CHANCE'))credit_line_amt, nvl(CLC.credit_line_amt/10000,(select q.finance_amount/10000 from prj_quotation q where q.source_document_id = clc.chance_id and q.source_document_category = 'HLS_CREDIT_LINE_CHANCE'))credit_line_amt_w, CLC.CREDIT_EXPOSURE_AMT, CLC.VALID_TO, CLC.CREDIT_FLAG, CASE CLC.CREDIT_FLAG WHEN 'Y' THEN '是' WHEN 'N' THEN '否' END CREDIT_FLAG_N, clc.APPROVED_DATE, clc.BUSINESS_TYPE, (select v.description from hls_business_type v where v.enabled_flag = 'Y' and v.DOCUMENT_CATEGORY = 'CHANCE' and clc.BUSINESS_TYPE = V.business_type) BUSINESS_TYPE_N, clc.PROPOSER_EMPLOYEE_ID , (SELECT a.description FROM sys_user a WHERE a.user_id = clc.PROPOSER_EMPLOYEE_ID) as PROPOSER_EMPLOYEE_ID_N,
clc.PROJECT_ASSISTANT , (SELECT a.description FROM sys_user a WHERE a.user_id = clc.PROJECT_ASSISTANT) as PROJECT_ASSISTANT_N, clc.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=clc.unit_id) as unit_id_n, CLC.CREDIT_LINE_STATUS, (select v.MEANING from sys_code_value_b_v v where v.code='CREDIT.APPROVE_STATUS' and v.code_value=clc.CREDIT_LINE_STATUS) as credit_line_status_n, CLC.VALID_FROM, to_char(clc.CREATION_DATE, 'yyyy-mm-dd') TOUCH_CREATED_DATE from HLS_CREDIT_LINE_CHANCE CLC where CLC.credit_line_status not in('CLOSED') and nvl(CLC.DATA_TYPE, 'NORMAL') not in ('CHANGE_REQ', 'HISTORY', 'CHANGE_REQ_HISTORY') and nvl(clc.chance_type, 'CHANCE') != 'CREDIT' order by clc.CREATION_DATE desc )tt
1=1
and ( tt.created_by = #{createdBy} or tt.PROJECT_ASSISTANT = #{createdBy} or #{request.employeeCode} in('ADMIN') OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN(select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=tt.created_by AND a.employee_assign_id=b.employee_assign_id)) )
and tt.credit_line_number like #{creditLineNumber}
and tt.credit_line_name like #{creditLineName}
and tt.project_reviewer_desc like #{projectReviewer}
and tt.CREDIT_LINE_AMT=#{creditLineAmt}
and credit_line_status=#{creditLineStatus}
and tt.proposer_employee_id=#{proposerEmployeeId}
and industry like concat(concat('%',#{industry}),'%')
and tt.project_assistant=#{projectAssistant}
and tt.CREDIT_LINE_STATUS=#{creditLineStatus}
AND TO_CHAR(creation_date, 'yyyy-MM-dd') BETWEEN #{creationDateFrom} AND #{creationDateTo}
and tt.CREDIT_LINE_AMT >= #{limitFrom}
and tt.CREDIT_LINE_AMT <= #{limitTo}
and tt.VALID_FROM >= #{validFrom}
and tt.VALID_TO < (#{endDate} + 1)
and bp_id_n like concat(concat('%',#{bpIdN}),'%')
and tt.marketing_report_id = #{marketingReportNumber}
and tt.BUSINESS_TYPE = #{businessType}
and tt.bp_name like concat(concat('%',#{bpName}),'%')
and tt.credit_flag = #{creditFlag}
and tt.unit_id_n = #{unitIdN}
